//! THIRD-PARTY-NOTICES.md reproduces every required copyright and licence
//! notice, so a binary release is compliant (ADR-0010).
//!
//! The crate and package part is generated by
//! `scripts/licenses/generate-notices.sh` from the lockfiles, and CI's
//! `notices` job fails when the committed file is stale. These tests guard
//! what a stale or hand-edited file would get wrong without anyone running
//! the generator: that it is the generated file at all, that every direct
//! dependency has an entry, and that every entry still exists.

use std::collections::BTreeSet;
use std::path::PathBuf;

fn read(rel: &str) -> String {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
    std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
}

fn notices() -> String {
    read("../THIRD-PARTY-NOTICES.md")
}

/// The keys of every `[...dependencies]` table of a Cargo.toml that is not a
/// build or dev table, with `package = ` renames resolved.
fn shipped_dependencies(cargo_toml: &str) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    let mut in_deps = false;
    for line in cargo_toml.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            in_deps = t.ends_with("dependencies]")
                && !t.contains("dev-dependencies")
                && !t.contains("build-dependencies");
            continue;
        }
        if !in_deps || t.starts_with('#') || !t.contains('=') {
            continue;
        }
        let key = t.split('=').next().unwrap().trim();
        if key.is_empty()
            || !key
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
        {
            continue;
        }
        let name = t
            .split("package = \"")
            .nth(1)
            .and_then(|r| r.split('"').next())
            .unwrap_or(key);
        out.insert(name.to_string());
    }
    out
}

/// Crate names in the notices' Rust table.
fn listed_crates(notices: &str) -> BTreeSet<String> {
    let rust = notices
        .split("## Rust crates")
        .nth(1)
        .and_then(|s| s.split("### Licence texts").next())
        .expect("a Rust crates table");
    rust.lines()
        .filter_map(|l| l.strip_prefix("| `"))
        .filter_map(|l| l.split('`').next())
        .map(str::to_string)
        .collect()
}

#[test]
fn notices_are_generated_not_hand_kept() {
    let n = notices();
    assert!(n.contains("generated by scripts/licenses/generate-notices.sh"));
    assert!(!n.contains("Status: incomplete"));
    assert!(n.contains("## Rust crates"));
    assert!(n.contains("## Frontend packages"));
    // The installer stub's own notice (NSIS) is reproduced, not just named.
    assert!(n.contains("ZLIB/LIBPNG LICENSE"));
    // SumatraPDF is the version the fetch scripts pin.
    assert!(n.contains("### SumatraPDF 3.6.1"));
}

#[test]
fn every_direct_rust_dependency_has_a_notice() {
    let listed = listed_crates(&notices());
    assert!(listed.len() > 300, "{} crates listed", listed.len());
    for manifest in ["Cargo.toml", "../shell-ext-win/Cargo.toml"] {
        let deps = shipped_dependencies(&read(manifest));
        assert!(deps.contains("windows"), "{manifest}: {deps:?}");
        for dep in deps {
            assert!(
                listed.contains(&dep),
                "{manifest}: `{dep}` has no entry in THIRD-PARTY-NOTICES.md; run scripts/licenses/generate-notices.sh"
            );
        }
    }
}

#[test]
fn every_listed_crate_is_still_in_a_lockfile() {
    let locks = read("Cargo.lock") + &read("../shell-ext-win/Cargo.lock");
    for name in listed_crates(&notices()) {
        assert!(
            locks.contains(&format!("name = \"{name}\"\n")),
            "THIRD-PARTY-NOTICES.md lists `{name}`, which no lockfile has; run scripts/licenses/generate-notices.sh"
        );
    }
}

#[test]
fn every_frontend_dependency_has_a_notice() {
    let n = notices();
    let pkg: serde_json::Value = serde_json::from_str(&read("../package.json")).unwrap();
    let deps = pkg["dependencies"].as_object().unwrap();
    for name in deps.keys().map(String::as_str).chain(["tailwindcss"]) {
        assert!(
            n.contains(&format!("### `{name}` ")),
            "`{name}` has no notice; run scripts/licenses/generate-notices.sh"
        );
    }
}
